  tools.exec_command({cmd:"find .. -name AGENTS.md -print",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"sed -n '1,300p' src/components/structures/RoomSearchView.tsx",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"sed -n '1,340p' src/components/views/rooms/SearchResultTile.tsx",workdir:"/app",max_output_tokens:14000}),
  tools.exec_command({cmd:"ls -la .codex-role-output 2>/dev/null; sed -n '1,120p' .codex-role-output/checkpoint.md 2>/dev/null",workdir:"/app",max_output_tokens:2000})
]); out.forEach((r,i)=>text(`RESULT ${i}\n${r.status==="fulfilled"?r.value.output:r.reason}`));

